SELECT w.w_warehouse_name, cd.cd_gender, AVG(ss.ss_net_profit) AS avg_profit, AVG(cr.cr_net_loss) AS avg_loss, AVG(ss.ss_net_profit) - AVG(cr.cr_net_loss) AS net_avg_gain, DENSE_RANK() OVER (ORDER BY AVG(cr.cr_net_loss) ASC) AS low_loss_rank, CASE WHEN AVG(cr.cr_net_loss) BETWEEN 0 AND 2000 THEN 'Low' WHEN AVG(cr.cr_net_loss) BETWEEN 2000 AND 8000 THEN 'Medium' ELSE 'High' END AS loss_level FROM warehouse w LEFT JOIN catalog_returns cr ON cr.cr_warehouse_sk = w.w_warehouse_sk LEFT JOIN customer_demographics cd ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk LEFT JOIN store_sales ss ON ss.ss_cdemo_sk = cd.cd_demo_sk GROUP BY w.w_warehouse_name, cd.cd_gender HAVING COUNT(ss.ss_ticket_number) > 50 ORDER BY net_avg_gain DESC LIMIT 15
